formulas.gurps_3d6_resolution:
function resolve3d6(target) {
  const rolls = rollDice(3, 6), total = sum(rolls), isCritSuccess = total === 3 || total === 4 || total === 5 && target >= 15, isCritFail = total >= 18 || total === 17 && target <= 15, success = total <= target && !isCritFail, margin = target - total;
  let outcome;
  if (isCritSuccess)
    outcome = "critical-success";
  else if (isCritFail)
    outcome = "critical-failure";
  else if (success)
    outcome = "success";
  else
    outcome = "failure";
  const breakdown = `3d6(${rolls.join("+")}) = ${total} vs target ${target} \u2192 ${outcome.replace("-", " ").toUpperCase()}`;
  return { rolls, total, target, margin, outcome, breakdown };
}

formulas.thrust_damage:
function gurpsThrust(st) {
  const s = Math.max(4, Math.min(50, st));
  let dice = 1, flat = 0;
  if (s <= 9)
    flat = s <= 7 ? -4 : s === 8 ? -3 : -2;
  else if (s <= 11)
    flat = s === 10 ? -2 : -1;
  else if (s <= 17)
    flat = Math.floor((s - 12) / 2);
  else {
    dice = 2 + Math.floor((s - 18) / 8);
    flat = Math.floor((s - 18) % 8 / 2) - 1;
  }
  const flatText = flat > 0 ? `+${flat}` : flat < 0 ? `${flat}` : "";
  return { notation: `${dice}d6${flatText}`, flat };
}

formulas.swing_damage:
function gurpsSwing(st) {
  const s = Math.max(4, Math.min(50, st));
  let dice = 1, flat = 0;
  if (s <= 9)
    flat = s - 10;
  else if (s <= 12)
    flat = s - 10;
  else if (s <= 17) {
    dice = 2;
    flat = Math.floor((s - 13) / 2) - 1;
  } else {
    dice = 2 + Math.floor((s - 14) / 8);
    flat = Math.floor((s - 14) % 8 / 2);
  }
  const flatText = flat > 0 ? `+${flat}` : flat < 0 ? `${flat}` : "";
  return { notation: `${dice}d6${flatText}`, flat };
}

formulas.skill_level:
function gurpsSkillLevel(stat, difficulty, points) {
  const offset = difficulty === "easy" ? 0 : difficulty === "average" ? -1 : -2;
  if (points <= 0)
    return stat - 5;
  if (points === 1)
    return stat + offset;
  if (points === 2)
    return stat + offset + 1;
  if (points === 4)
    return stat + offset + 2;
  return stat + offset + 2 + Math.floor((points - 4) / 4);
}

formulas.skill_upgrade_cost:
function gurpsSkillUpgradeCost(points) {
  if (points <= 0)
    return 1;
  if (points === 1)
    return 1;
  if (points === 2)
    return 2;
  if (points === 4)
    return 4;
  return 4;
}
